let face = mix(warm, c3, 0.24 * smoothstep(-0.5, 0.5, a.x));
let front = mix(face, c5, clamp(vein * 0.65 + branches, 0.0, 0.75));

let r = vec2<f32>(p.x - breeze * 0.42 + 3.7, p.y + t * fall_speed * 0.28) * density * 1.5;
